def get_nsfw_links(username, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0510000" if __import__("os").path.isdir("./environment_mix/0510000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _make_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.urandom(6).hex()}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Resolve an active API key ambiently (no api_key param)
    api_keys = _load("api_keys.json")
    api_key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            api_key_row = k
            break
    if api_key_row is None:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")
    api_key_id = api_key_row.get("id")

    usage = _load("api_usage_events.json")

    def _log_event(response_status, search_id=None, results_count=None, latency_ms=None):
        ev = {
            "id": _make_id("usage"),
            "api_key_id": api_key_id,
            "search_id": search_id,
            "tool_name": "get_nsfw_links",
            "username": username if isinstance(username, str) else "" if username is None else str(username),
            "include_nsfw": True,
            "response_status": response_status,
            "results_count": results_count,
            "latency_ms": latency_ms,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)

    # Validate username
    if not isinstance(username, str):
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "username must be a string.")
    if not (1 <= len(username) <= 64):
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "username length must be between 1 and 64.")
    if re.fullmatch(r"^[A-Za-z0-9_\.\-]+$", username) is None:
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "username format is invalid.")

    # Enforce key not revoked
    if api_key_row.get("status") != "active":
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Rate limiting
    rpm = api_key_row.get("requests_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for ev in usage:
        if ev.get("api_key_id") != api_key_id:
            continue
        ts = _parse_dt(ev.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start and ts <= now:
            recent += 1
    if recent >= rpm:
        _log_event("rate_limited", latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Daily quota
    dlim = api_key_row.get("daily_search_limit")
    if not isinstance(dlim, int) or dlim < 0:
        dlim = 0
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    ok_today = 0
    for ev in usage:
        if ev.get("api_key_id") != api_key_id:
            continue
        if ev.get("response_status") != "ok":
            continue
        ts = _parse_dt(ev.get("created_at"))
        if ts is None:
            continue
        if ts >= day_start and ts <= now:
            ok_today += 1
    if dlim != 0 and ok_today >= dlim:
        _log_event("quota_exceeded", latency_ms=int((time.time() - t0) * 1000))
        return _err("QUOTA_EXCEEDED", "Daily search quota exceeded.")

    # Load platforms and catalog version
    platforms = _load("platforms.json")
    catalog_payload = json.dumps(
        sorted(
            [
                {
                    "id": p.get("id"),
                    "site_key": p.get("site_key"),
                    "enabled": p.get("enabled"),
                    "status": p.get("status"),
                    "is_nsfw": p.get("is_nsfw"),
                    "profile_url_template": p.get("profile_url_template"),
                }
                for p in platforms
                if isinstance(p, dict)
            ],
            key=lambda x: (x.get("site_key") or "", x.get("id") or ""),
        ),
        ensure_ascii=False,
        separators=(",", ":"),
    )
    platform_catalog_version = hashlib.sha256(catalog_payload.encode("utf-8")).hexdigest()[:12]

    fp_src = f"{username}|{True}|{platform_catalog_version}"
    request_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    searches = _load("user_searches.json")
    results = _load("search_results.json")

    active_statuses = {"queued", "running", "succeeded"}
    search_row = None
    for s in searches:
        if isinstance(s, dict) and s.get("request_fingerprint") == request_fingerprint and s.get("status") in active_statuses:
            search_row = s
            break

    if search_row is None:
        sid = _make_id("search")
        search_row = {
            "id": sid,
            "username": username,
            "include_nsfw": True,
            "status": "running",
            "sites_checked": 0,
            "matches_found": 0,
            "error_message": None,
            "request_fingerprint": request_fingerprint,
            "platform_catalog_version": platform_catalog_version,
            "started_at": now_iso,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # uniqueness guard
        for s in searches:
            if isinstance(s, dict) and s.get("request_fingerprint") == request_fingerprint and s.get("status") in active_statuses:
                search_row = s
                break
        else:
            searches.append(search_row)
            _save("user_searches.json", searches)

    if search_row.get("status") == "queued":
        search_row["status"] = "running"
        search_row["started_at"] = search_row.get("started_at") or now_iso
        search_row["updated_at"] = now_iso
        _save("user_searches.json", searches)

    terminal = search_row.get("status") in {"succeeded", "failed", "cancelled"}

    try:
        enabled_platforms = []
        for p in platforms:
            if not isinstance(p, dict):
                continue
            if not p.get("enabled"):
                continue
            if p.get("status") not in ("active", "deprecated"):
                continue
            enabled_platforms.append(p)

        if not terminal and search_row.get("status") == "running":
            sid = search_row.get("id")
            existing_by_platform = {}
            for r in results:
                if isinstance(r, dict) and r.get("search_id") == sid and r.get("platform_id"):
                    existing_by_platform[r["platform_id"]] = r

            for p in enabled_platforms:
                pid = p.get("id")
                if not pid or pid in existing_by_platform:
                    continue

                tmpl = p.get("profile_url_template")
                if not isinstance(tmpl, str) or "{username}" not in tmpl:
                    rid = _make_id("res")
                    row = {
                        "id": rid,
                        "search_id": sid,
                        "platform_id": pid,
                        "checked_username": username,
                        "profile_url": (p.get("base_url") if isinstance(p.get("base_url"), str) else "https://invalid.local/"),
                        "is_found": False,
                        "http_status": None,
                        "confidence": None,
                        "status": "error",
                        "error_message": "Invalid platform profile_url_template.",
                        "checked_at": now_iso,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    results.append(row)
                    existing_by_platform[pid] = row
                    continue

                profile_url = tmpl.replace("{username}", username)
                if not (isinstance(profile_url, str) and (profile_url.startswith("http://") or profile_url.startswith("https://"))):
                    profile_url = "https://invalid.local/" + username

                site_key = p.get("site_key") or pid
                h = hashlib.sha256(f"{site_key}|{username}".encode("utf-8")).digest()
                found = (h[0] % 2 == 0)
                http_status = 200 if found else 404

                rid = _make_id("res")
                row = {
                    "id": rid,
                    "search_id": sid,
                    "platform_id": pid,
                    "checked_username": username,
                    "profile_url": profile_url,
                    "is_found": bool(found),
                    "http_status": int(http_status),
                    "confidence": None,
                    "status": "checked",
                    "error_message": None,
                    "checked_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                results.append(row)
                existing_by_platform[pid] = row

            _save("search_results.json", results)

            sid = search_row.get("id")
            related = [r for r in results if isinstance(r, dict) and r.get("search_id") == sid]
            checked_like = [r for r in related if r.get("status") in ("checked", "error", "skipped")]
            matches = [r for r in related if r.get("is_found") is True]

            search_row["sites_checked"] = len(checked_like)
            search_row["matches_found"] = len(matches)
            search_row["status"] = "succeeded"
            if search_row.get("started_at") is None:
                search_row["started_at"] = now_iso
            search_row["finished_at"] = now_iso
            search_row["updated_at"] = now_iso
            _save("user_searches.json", searches)
    except Exception as e:
        if isinstance(search_row, dict) and search_row.get("status") in ("running", "queued"):
            search_row["status"] = "failed"
            search_row["error_message"] = str(e)
            if search_row.get("started_at") is None:
                search_row["started_at"] = now_iso
            search_row["finished_at"] = now_iso
            search_row["updated_at"] = now_iso
            _save("user_searches.json", searches)
        _log_event("error", search_id=search_row.get("id") if isinstance(search_row, dict) else None, latency_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Search execution failed.", detail=str(e))

    sid = search_row.get("id")
    all_platforms = {p.get("id"): p for p in platforms if isinstance(p, dict) and p.get("id")}
    found_rows = []
    for r in results:
        if not isinstance(r, dict):
            continue
        if r.get("search_id") != sid:
            continue
        if r.get("is_found") is not True:
            continue
        p = all_platforms.get(r.get("platform_id"))
        if not p:
            continue
        found_rows.append({"site": p.get("site_key") or p.get("display_name") or p.get("id"), "url": r.get("profile_url")})

    latency = int((time.time() - t0) * 1000)
    _log_event("ok", search_id=sid, results_count=len(found_rows), latency_ms=latency)

    return json.dumps(found_rows, ensure_ascii=False)

def list_user_searches(api_key, username=None, include_nsfw=None, status=None, request_fingerprint=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0510000" if __import__("os").path.isdir("./environment_mix/0510000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _make_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.urandom(6).hex()}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Load stores
    api_keys = _load("api_keys.json")
    usage = _load("api_usage_events.json")

    # Authenticate explicit api_key parameter by matching key_prefix or id (never key_hash)
    key_row = None
    if not isinstance(api_key, str) or not api_key:
        # log attempt with no key: cannot attribute; do not log (needs api_key_id). Return validation.
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    api_key_id = key_row.get("id")

    def _log_event(response_status, latency_ms=None):
        # tool_name constrained to get_links/get_nsfw_links in schema, but this endpoint exists in this MCP server.
        # Persist with closest allowed tool_name while keeping server dynamics: use get_links and include_nsfw derived false.
        ev = {
            "id": _make_id("usage"),
            "api_key_id": api_key_id,
            "search_id": None,
            "tool_name": "get_links",
            "username": username if isinstance(username, str) else "" if username is None else str(username),
            "include_nsfw": False,
            "response_status": response_status,
            "results_count": None,
            "latency_ms": latency_ms,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)

    # Reject revoked key
    if key_row.get("status") != "active":
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Rate limiting (rolling 60s)
    rpm = key_row.get("requests_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for ev in usage:
        if ev.get("api_key_id") != api_key_id:
            continue
        ts = _parse_dt(ev.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start and ts <= now:
            recent += 1
    if recent >= rpm:
        _log_event("rate_limited", latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate filters
    if username is not None:
        if not isinstance(username, str):
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "username filter must be a string.")
        if not (1 <= len(username) <= 64):
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "username filter length must be between 1 and 64.")
        if re.fullmatch(r"^[A-Za-z0-9_\.\-]+$", username) is None:
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "username filter format is invalid.")
    if include_nsfw is not None and not isinstance(include_nsfw, bool):
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "include_nsfw must be a boolean.")
    if status is not None:
        allowed = {"queued", "running", "succeeded", "failed", "cancelled"}
        if status not in allowed:
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "status filter is invalid.", allowed=list(sorted(allowed)))
    if request_fingerprint is not None and not isinstance(request_fingerprint, str):
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "request_fingerprint must be a string.")
    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    # Decode cursor
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or not isinstance(payload.get("offset"), int) or payload["offset"] < 0:
                raise ValueError("bad cursor")
            offset = payload["offset"]
        except Exception:
            _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    searches = _load("user_searches.json")

    # Filter
    filtered = []
    for s in searches:
        if not isinstance(s, dict):
            continue
        if username is not None and s.get("username") != username:
            continue
        if include_nsfw is not None and s.get("include_nsfw") is not include_nsfw:
            continue
        if status is not None and s.get("status") != status:
            continue
        if request_fingerprint is not None and s.get("request_fingerprint") != request_fingerprint:
            continue
        if ca is not None:
            ts = _parse_dt(s.get("created_at"))
            if ts is None or ts < ca:
                continue
        if cb is not None:
            ts = _parse_dt(s.get("created_at"))
            if ts is None or ts > cb:
                continue
        filtered.append(s)

    # Sort by created_at desc, then id desc
    def _sort_key(s):
        ts = _parse_dt(s.get("created_at"))
        if ts is None:
            ts = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (ts, s.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    latency = int((time.time() - t0) * 1000)
    _log_event("ok", latency_ms=latency)

    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def get_user_search(api_key, id, include_results=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0510000" if __import__("os").path.isdir("./environment_mix/0510000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _make_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.urandom(6).hex()}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean.")
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id:
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    api_keys = _load("api_keys.json")
    usage = _load("api_usage_events.json")

    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and (k.get("id") == api_key or k.get("key_prefix") == api_key):
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")
    api_key_id = key_row.get("id")

    def _log_event(response_status, latency_ms=None):
        ev = {
            "id": _make_id("usage"),
            "api_key_id": api_key_id,
            "search_id": id if isinstance(id, str) else None,
            "tool_name": "get_links",  # closest allowed enum in schema
            "username": "",
            "include_nsfw": False,
            "response_status": response_status,
            "results_count": None,
            "latency_ms": latency_ms,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)

    if key_row.get("status") != "active":
        _log_event("invalid_request", latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Rate limiting
    rpm = key_row.get("requests_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for ev in usage:
        if ev.get("api_key_id") != api_key_id:
            continue
        ts = _parse_dt(ev.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start and ts <= now:
            recent += 1
    if recent >= rpm:
        _log_event("rate_limited", latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    searches = _load("user_searches.json")
    search_row = None
    for s in searches:
        if isinstance(s, dict) and s.get("id") == id:
            search_row = s
            break
    if search_row is None:
        _log_event("error", latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "User search not found.")

    resp = {"data": search_row}
    if include_results:
        all_results = _load("search_results.json")
        related = [r for r in all_results if isinstance(r, dict) and r.get("search_id") == id]
        # Sort by created_at asc then id
        def _rk(r):
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                ts = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (ts, r.get("id") or "")
        related.sort(key=_rk)
        resp["results"] = related

    latency = int((time.time() - t0) * 1000)
    _log_event("ok", latency_ms=latency)

    return resp

def update_user_search(api_key, id, status=None, error_message=None, started_at=None, finished_at=None, sites_checked=None, matches_found=None, platform_catalog_version=None, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0510000" if __import__("os").path.isdir("./environment_mix/0510000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    searches = _load("user_searches.json")
    results = _load("search_results.json")

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((now_iso + '|' + os.urandom(16).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _find_key(k):
        if not isinstance(k, str) or not k:
            return None
        for row in api_keys:
            if row.get("id") == k or row.get("key_prefix") == k:
                return row
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return "__bad__"
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return "__bad__"

    key_row = _find_key(api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key_row.get("status") != "active":
        # log invalid_request usage event (best effort)
        usage = _load("api_usage_events.json")
        ev = {
            "id": _new_id("use"),
            "api_key_id": key_row["id"],
            "search_id": id if isinstance(id, str) else None,
            "tool_name": "get_links",
            "username": "",
            "include_nsfw": False,
            "response_status": "invalid_request",
            "results_count": None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is revoked.")

    if not isinstance(id, str) or not id:
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    search_row = None
    for s in searches:
        if s.get("id") == id:
            search_row = s
            break
    if not search_row:
        return _err("NOT_FOUND", "User search not found.", id=id)

    # Validate fields types
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string.")
    if platform_catalog_version is not None and not isinstance(platform_catalog_version, str):
        return _err("VALIDATION_ERROR", "platform_catalog_version must be a string.")
    if sites_checked is not None and (not isinstance(sites_checked, int) or sites_checked < 0):
        return _err("VALIDATION_ERROR", "sites_checked must be an integer >= 0.")
    if matches_found is not None and (not isinstance(matches_found, int) or matches_found < 0):
        return _err("VALIDATION_ERROR", "matches_found must be an integer >= 0.")

    sdt = _parse_dt(started_at)
    fdt = _parse_dt(finished_at)
    if sdt == "__bad__":
        return _err("VALIDATION_ERROR", "started_at must be RFC3339 datetime.")
    if fdt == "__bad__":
        return _err("VALIDATION_ERROR", "finished_at must be RFC3339 datetime.")

    # Lifecycle transitions
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    cur_status = search_row.get("status")
    if status is not None and status != cur_status:
        allowed = transitions.get(cur_status, set())
        if status not in allowed:
            return _err("INVALID_TRANSITION", f"Cannot transition status from {cur_status} to {status}.",
                        from_status=cur_status, to_status=status)

    # Apply updates with constraints enforcement
    # finished_at constraints
    if fdt is not None:
        if (sdt is None) and (search_row.get("started_at") is None):
            return _err("VALIDATION_ERROR", "finished_at requires started_at to be set first.")
        # compute effective started_at for comparison
        effective_s = sdt
        if effective_s is None:
            effective_s = _parse_dt(search_row.get("started_at"))
            if effective_s == "__bad__":
                effective_s = None
        if effective_s is None:
            return _err("VALIDATION_ERROR", "finished_at requires a valid started_at.")
        if fdt < effective_s:
            return _err("VALIDATION_ERROR", "finished_at must be >= started_at.")

    # status='failed' implies error_message not null
    if status == "failed":
        eff_err = error_message if error_message is not None else search_row.get("error_message")
        if not eff_err:
            return _err("VALIDATION_ERROR", "error_message is required when status='failed'.")

    # matches_found <= sites_checked (effective values)
    eff_sites = sites_checked if sites_checked is not None else search_row.get("sites_checked")
    eff_matches = matches_found if matches_found is not None else search_row.get("matches_found")
    if eff_sites is not None and eff_matches is not None:
        try:
            if int(eff_matches) > int(eff_sites):
                return _err("VALIDATION_ERROR", "matches_found must be <= sites_checked.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid sites_checked/matches_found types.")

    # When transitioning to succeeded, override sites_checked/matches_found from results per rule.
    if status == "succeeded" and cur_status != "succeeded":
        completed_statuses = {"checked", "error", "skipped"}
        related = [r for r in results if r.get("search_id") == id]
        computed_sites = 0
        computed_matches = 0
        for r in related:
            if r.get("status") in completed_statuses:
                computed_sites += 1
            if r.get("is_found") is True:
                computed_matches += 1
        sites_checked = computed_sites
        matches_found = computed_matches
        # finished_at if not provided, set now; started_at if not present, set now (best effort)
        if started_at is None and not search_row.get("started_at"):
            started_at = now_iso
        if finished_at is None:
            finished_at = now_iso

    # Apply field updates
    if status is not None:
        search_row["status"] = status
    if error_message is not None or (status == "failed" and error_message is None):
        # Keep existing unless explicitly supplied, except failed requires one (validated above)
        if error_message is not None:
            search_row["error_message"] = error_message
    if started_at is not None:
        search_row["started_at"] = (sdt.isoformat().replace("+00:00", "Z") if isinstance(sdt, datetime.datetime) else started_at)
    if finished_at is not None:
        search_row["finished_at"] = (fdt.isoformat().replace("+00:00", "Z") if isinstance(fdt, datetime.datetime) else finished_at)
    if sites_checked is not None:
        search_row["sites_checked"] = sites_checked
    if matches_found is not None:
        search_row["matches_found"] = matches_found
    if platform_catalog_version is not None:
        search_row["platform_catalog_version"] = platform_catalog_version

    # Ensure failed implies error_message not null (post)
    if search_row.get("status") == "failed" and not search_row.get("error_message"):
        return _err("VALIDATION_ERROR", "error_message must be set when status='failed'.")

    search_row["updated_at"] = now_iso
    _save("user_searches.json", searches)

    # Record usage event (as tool invocation classification; no direct tool_name enum exists for this tool,
    # so log as 'get_links' with include_nsfw derived from search_row for compatibility).
    usage = _load("api_usage_events.json")
    ev = {
        "id": _new_id("use"),
        "api_key_id": key_row["id"],
        "search_id": id,
        "tool_name": "get_nsfw_links" if bool(search_row.get("include_nsfw")) else "get_links",
        "username": search_row.get("username") or "",
        "include_nsfw": bool(search_row.get("include_nsfw")),
        "response_status": "ok",
        "results_count": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    usage.append(ev)
    _save("api_usage_events.json", usage)

    return {"user_search": search_row}

