    key_row = _find_key(api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key_row.get("status") != "active":
        ev = {
            "id": _new_id("use"),
            "api_key_id": key_row["id"],
            "search_id": None,
            "tool_name": "get_links",
            "username": "",
            "include_nsfw": False,
            "response_status": "invalid_request",
            "results_count": None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is revoked.")

    if status is not None and status not in ("active", "deprecated", "disabled"):
        ev = {
            "id": _new_id("use"),
            "api_key_id": key_row["id"],
            "search_id": None,
            "tool_name": "get_links",
            "username": "",
            "include_nsfw": False,
            "response_status": "invalid_request",
            "results_count": None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)
        return _err("VALIDATION_ERROR", "Invalid status filter.")

    if enabled is not None and not isinstance(enabled, bool):
        return _err("VALIDATION_ERROR", "enabled must be a boolean.")
    if is_nsfw is not None and not isinstance(is_nsfw, bool):
        return _err("VALIDATION_ERROR", "is_nsfw must be a boolean.")
    if site_key is not None and (not isinstance(site_key, str) or not site_key):
        return _err("VALIDATION_ERROR", "site_key must be a non-empty string.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("idx:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = platforms[:]
    # Deterministic ordering: site_key asc then id
    rows.sort(key=lambda r: (r.get("site_key") or "", r.get("id") or ""))

    def _match(p):
        if status is not None and p.get("status") != status:
            return False
        if enabled is not None and p.get("enabled") is not enabled:
            return False
        if is_nsfw is not None and p.get("is_nsfw") is not is_nsfw:
            return False
        if site_key is not None and p.get("site_key") != site_key:
            return False
        return True

    filtered = [p for p in rows if _match(p)]
    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"idx:{start+limit}".encode("utf-8")).decode("utf-8")

    # Log call as ok
    ev = {
        "id": _new_id("use"),
        "api_key_id": key_row["id"],
        "search_id": None,
        "tool_name": "get_links",
        "username": "",
        "include_nsfw": False,
        "response_status": "ok",
        "results_count": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    usage.append(ev)
    _save("api_usage_events.json", usage)

    return {
        "platforms": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }
    }

def get_whoami(api_key, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0510000" if __import__("os").path.isdir("./environment_mix/0510000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    api_keys = _load("api_keys.json")
    usage = _load("api_usage_events.json")

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((now_iso + '|' + os.urandom(16).hex()).encode('utf-8')).hexdigest()[:24]}"

    def _find_key(k):
        if not isinstance(k, str) or not k:
            return None
        for row in api_keys:
            if row.get("id") == k or row.get("key_prefix") == k:
                return row
        return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    key_row = _find_key(api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key.")
    if key_row.get("status") != "active":
        ev = {
            "id": _new_id("use"),
            "api_key_id": key_row["id"],
            "search_id": None,
            "tool_name": "get_links",
            "username": "",
            "include_nsfw": False,
            "response_status": "invalid_request",
            "results_count": None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(ev)
        _save("api_usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Compute current rate usage (rolling 60 seconds)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for ev in usage:
        if ev.get("api_key_id") != key_row["id"]:
            continue
        dt = _parse_dt(ev.get("created_at"))
        if dt and dt >= window_start:
            recent += 1

    # Compute quota usage for current UTC day: count of ok events
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    ok_today = 0
    for ev in usage:
        if ev.get("api_key_id") != key_row["id"]:
            continue
        if ev.get("response_status") != "ok":
            continue
        dt = _parse_dt(ev.get("created_at"))
        if dt and dt >= day_start and dt <= now:
            ok_today += 1

    # Log whoami call
    log_ev = {
        "id": _new_id("use"),
        "api_key_id": key_row["id"],
        "search_id": None,
        "tool_name": "get_links",
        "username": "",
        "include_nsfw": False,
        "response_status": "ok",
        "results_count": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    usage.append(log_ev)
    _save("api_usage_events.json", usage)

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "status": key_row.get("status"),
            "label": key_row.get("label"),
            "requests_per_minute": key_row.get("requests_per_minute"),
            "daily_search_limit": key_row.get("daily_search_limit"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "revoked_at": key_row.get("revoked_at"),
        },
        "entitlements": {
            "can_search": key_row.get("status") == "active",
            "include_nsfw_allowed": True,
        },
        "usage": {
            "rate_limit": {
                "window_seconds": 60,
                "limit": key_row.get("requests_per_minute"),
                "used": recent,
                "remaining": max(0, int(key_row.get("requests_per_minute") or 0) - recent) if isinstance(key_row.get("requests_per_minute"), int) else None,
            },
            "daily_quota": {
                "day_start_utc": day_start.isoformat().replace("+00:00", "Z"),
                "limit": key_row.get("daily_search_limit"),
                "used_ok": ok_today,
                "remaining_ok": (max(0, int(key_row.get("daily_search_limit")) - ok_today) if isinstance(key_row.get("daily_search_limit"), int) else None),
            }
        }
    }
